execution_after_authorization.upload_command_and_public_byte_verificat:
$ErrorActionPreference = 'Stop'
$m = Get-Content project-state/discovery/later-ms4-r2-upload-preflight-2026-09-24.json -Raw | ConvertFrom-Json
& .\scripts\project\Get-R2Inventory.ps1 -OutputPath tmp/later-ms4-r2-at-upload-start.json | Out-Null
$before = Get-Content tmp/later-ms4-r2-at-upload-start.json -Raw | ConvertFrom-Json
if ($before.object_count -ne $m.r2_baseline.object_count -or $before.total_bytes -ne $m.r2_baseline.total_bytes) { throw 'R2 baseline changed; repeat the read-only preflight' }
foreach ($r in $m.records) {
  if (@($before.objects | Where-Object { $_.key.ToLowerInvariant() -eq $r.proposed_r2_key.ToLowerInvariant() }).Count) { throw "R2 key now exists: $($r.id)" }
}
foreach ($r in $m.records) {
  $f = Get-Item -LiteralPath $r.staged_path
  $h = (Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()
  if ($f.Length -ne $r.source_size_bytes -or $h -ne $r.source_sha256) { throw "Staged bytes changed: $($r.id)" }
  & .\scripts\upload-r2-document.ps1 -SourcePath $r.staged_path -ObjectKey $r.proposed_r2_key -MaxObjectBytes 150000000 -MaxProjectedStorageBytes 10000000000
  $v = & .\scripts\project\Test-R2PublicObject.ps1 -SourcePath $r.staged_path -PublicUrl ([uri]$r.expected_public_archive_url)
  if (-not $v.byte_identical -or $v.size_bytes -ne $r.source_size_bytes -or $v.checksum_sha256 -ne $r.source_sha256) { throw "Public bytes changed: $($r.id)" }
}
& .\scripts\project\Get-R2Inventory.ps1 -OutputPath tmp/later-ms4-r2-postupload.json | Out-Null
$after = Get-Content tmp/later-ms4-r2-postupload.json -Raw | ConvertFrom-Json
if ($after.object_count -ne 1237 -or $after.total_bytes -ne 9218281842) { throw 'Unexpected post-upload R2 totals' }
$afterByKey = @{}; foreach ($object in $after.objects) { $afterByKey[$object.key] = $object }
foreach ($old in $before.objects) {
  if (-not $afterByKey.ContainsKey($old.key) -or $afterByKey[$old.key].size_bytes -ne $old.size_bytes -or $afterByKey[$old.key].etag -ne $old.etag) { throw "Pre-existing R2 object changed: $($old.key)" }
}
foreach ($r in $m.records) {
  $object = @($after.objects | Where-Object key -CEQ $r.proposed_r2_key)
  if ($object.Count -ne 1 -or $object[0].size_bytes -ne $r.source_size_bytes) { throw "Missing or incorrect new R2 object: $($r.id)" }
}
# Reconcile saved R2 inventory and candidate metadata only after all six public-byte checks pass.
